/** Digital signatures (Schnorr, RSA-FDH) and zero-knowledge identification protocols, toy-sized. */
import { useMemo, useState } from 'react';
import { KV, Seg, Slider, VizFrame } from '../kit';
import { makeRng } from '../../math/random';
import { modInv, modPow } from '../../math/crypto/numberTheory';
import { truncHash } from '../../math/crypto/sha256';

// Group: p = 2039 = 2·1019 + 1, subgroup of prime order q = 1019 generated by b = 2² = 4.
const p = 2039n;
const q = 1019n;
const b = 4n;
const md = (x: bigint, n: bigint) => ((x % n) + n) % n;
/** Hash into Z_q^× (toy: truncated SHA-256). */
const Hq = (s: string) => {
  const v = BigInt(truncHash(s, 30)) % q;
  return v === 0n ? 1n : v;
};

// ------------------------------------------------------------------ signatures

export function SignatureLab({ tab: t0 = 'schnorr' }: Record<string, unknown>) {
  const [tab, setTab] = useState<'schnorr' | 'rsa'>(t0 === 'rsa' ? 'rsa' : 'schnorr');
  return (
    <VizFrame title="Digital signatures" caption="A signature scheme (Gen, S, V) is secure if no efficient adversary, after obtaining signatures on messages of its choice, can produce a valid signature on a new message (existential forgery). Unlike a MAC anyone with the public key can verify, which gives non-repudiation.">
      <Seg value={tab} onChange={setTab} options={[{ v: 'schnorr', label: 'Schnorr & nonce reuse' }, { v: 'rsa', label: 'RSA full-domain hash' }]} />
      <div style={{ marginTop: 10 }}>{tab === 'schnorr' ? <Schnorr /> : <RsaFdh />}</div>
    </VizFrame>
  );
}

function Schnorr() {
  const [k, setK] = useState(345);
  const [m1, setM1] = useState('I owe Bob 10 EUR');
  const [m2, setM2] = useState('I owe Bob 99 EUR');
  const [r1, setR1] = useState(123);
  const [reuse, setReuse] = useState(true);
  const [r2, setR2] = useState(777);
  const K = BigInt(k);
  const kappa = modPow(b, K, p);
  const sign = (m: string, r: bigint) => {
    const rho = modPow(b, r, p);
    const h = Hq(`${m}|${rho}`);
    const z = md(K * h + r, q);
    return { rho, h, z };
  };
  const verify = (m: string, s: { rho: bigint; z: bigint }) => {
    const h = Hq(`${m}|${s.rho}`);
    const v = md(modPow(b, s.z, p) * modPow(modInv(kappa, p)!, h, p), p);
    return v === s.rho;
  };
  const s1 = sign(m1, BigInt(r1));
  const s2 = sign(m2, BigInt(reuse ? r1 : r2));
  const sameRho = s1.rho === s2.rho;
  const dh = md(s1.h - s2.h, q);
  const kRec = sameRho && dh !== 0n ? md((s1.z - s2.z) * modInv(dh, q)!, q) : null;
  return (
    <>
      <p className="small">
        Public parameters: p = 2039, a subgroup of prime order q = 1019 generated by b = 4. Secret key k, public key κ = b^k. Sign: pick a fresh random r, ρ = b^r, z = k·h(m‖ρ) + r mod q, signature (ρ, z). Verify: b^z · κ^(−h(m‖ρ)) = ρ.
      </p>
      <div className="viz-controls">
        <Slider label="secret key k" value={k} min={1} max={1018} step={1} onChange={setK} />
        <Slider label="nonce r for signature 1" value={r1} min={1} max={1018} step={1} onChange={setR1} />
        <label className="row small" style={{ gap: 6 }}>
          <input type="checkbox" checked={reuse} onChange={(e) => setReuse(e.target.checked)} /> buggy RNG: reuse r for signature 2
        </label>
        {!reuse && <Slider label="nonce r for signature 2" value={r2} min={1} max={1018} step={1} onChange={setR2} />}
      </div>
      <div className="grid cols-2" style={{ gap: 8 }}>
        {[
          { m: m1, set: setM1, s: s1 },
          { m: m2, set: setM2, s: s2 },
        ].map((x, i) => (
          <div key={i} className="card tight">
            <label className="field">
              message {i + 1}
              <input type="text" value={x.m} onChange={(e) => x.set(e.target.value)} />
            </label>
            <div className="small mono">
              ρ = {String(x.s.rho)}, h = {String(x.s.h)}, z = {String(x.s.z)}
            </div>
            <span className={`verdict ${verify(x.m, x.s) ? 'good' : 'bad'}`}>{verify(x.m, x.s) ? 'valid' : 'invalid'}</span>
          </div>
        ))}
      </div>
      <KV items={[{ k: 'public key κ = b^k mod p', v: String(kappa) }]} />
      {sameRho ? (
        <div className="callout bad small">
          Both signatures have the same ρ, so the attacker knows they used the same r. Subtracting: z₁ − z₂ = k·(h₁ − h₂) (mod q), hence k = (z₁ − z₂)·(h₁ − h₂)⁻¹ mod q = <b>{kRec === null ? '?' : String(kRec)}</b>
          {kRec === K ? ' — the secret key, recovered from two public signatures.' : ''} This is how the PlayStation 3 ECDSA key leaked (constant nonce). The same algebra breaks DSA/ECDSA.
        </div>
      ) : (
        <div className="callout good small">Different nonces: the two equations z = k·h + r have two extra unknowns r₁, r₂, so they do not determine k.</div>
      )}
    </>
  );
}

const N = 3233n; // 61·53
const E = 17n;
const D = 2753n;

function RsaFdh() {
  const [m1, setM1] = useState(5);
  const [m2, setM2] = useState(7);
  const [msg, setMsg] = useState('pay 10 EUR');
  const s = (x: bigint) => modPow(x, D, N);
  const v = (x: bigint, sig: bigint) => modPow(sig, E, N) === md(x, N);
  const M1 = BigInt(m1);
  const M2 = BigInt(m2);
  const forged = md(s(M1) * s(M2), N);
  const hm = BigInt(truncHash(msg, 11)) % N;
  return (
    <>
      <p className="small">
        Full-domain hash with the RSA trapdoor: σ = h(m)^d mod N, verify σ^e ≡ h(m). Here N = 61·53 = 3233, e = 17, d = 2753.
      </p>
      <div className="card tight">
        <b>Without the hash (“textbook RSA signatures”)</b>
        <div className="viz-controls">
          <Slider label="m₁" value={m1} min={2} max={60} step={1} onChange={setM1} />
          <Slider label="m₂" value={m2} min={2} max={60} step={1} onChange={setM2} />
        </div>
        <div className="small mono">
          σ₁ = {m1}^d = {String(s(M1))}, σ₂ = {m2}^d = {String(s(M2))}; σ₁·σ₂ mod N = {String(forged)} is a valid signature of m₁·m₂ = {m1 * m2}: {v(M1 * M2, forged) ? '✓ verifies' : '✗'}
        </div>
        <div className="small">
          Multiplicativity gives forgeries from two signing queries. Even with no queries, any σ is a valid signature of the “message” σ^e mod N (here σ = 100 signs {String(modPow(100n, E, N))}).
        </div>
      </div>
      <div className="card tight" style={{ marginTop: 8 }}>
        <b>With a hash</b>
        <label className="field">
          message
          <input type="text" value={msg} onChange={(e) => setMsg(e.target.value)} />
        </label>
        <div className="small mono">
          h(m) = {String(hm)}, σ = h(m)^d mod N = {String(s(hm))}
        </div>
        <div className="small">
          To reuse the tricks the attacker would need a message whose hash equals σ₁σ₂ or σ^e — a preimage. Collision resistance is also required: h(m) = h(m′) would let a signature on m serve for m′. With a secure trapdoor
          permutation and h modelled as a random oracle, FDH is secure.
        </div>
      </div>
    </>
  );
}

// ------------------------------------------------------------------ zero knowledge

interface Transcript {
  y: bigint;
  c: bigint;
  z: bigint;
  ok: boolean;
}

export function ZkProof() {
  const [k, setK] = useState(271);
  const [cBits, setCBits] = useState(1);
  const [rounds, setRounds] = useState(5);
  const [honest, setHonest] = useState(true);
  const [seed, setSeed] = useState(1);
  const K = BigInt(k);
  const kappa = modPow(b, K, p);
  const kinv = modInv(kappa, p)!;
  const C = 2 ** cBits; // challenge space size
  const run = (rng: ReturnType<typeof makeRng>, isHonest: boolean, t: number): Transcript[] => {
    const out: Transcript[] = [];
    for (let i = 0; i < t; i++) {
      let y: bigint, z: bigint;
      let guess = 0n;
      if (isHonest) {
        const r = BigInt(rng.int(1, 1018));
        y = modPow(b, r, p);
        const c = BigInt(rng.int(0, C - 1));
        z = md(K * c + r, q);
        out.push({ y, c, z, ok: verifyT(y, c, z) });
        continue;
      }
      // cheater: guess the challenge, prepare y so that a random z verifies for that challenge
      guess = BigInt(rng.int(0, C - 1));
      z = BigInt(rng.int(0, 1018));
      y = md(modPow(b, z, p) * modPow(kinv, guess, p), p);
      const c = BigInt(rng.int(0, C - 1));
      // if the challenge differs, the cheater cannot answer (would need k)
      const zz = c === guess ? z : BigInt(rng.int(0, 1018));
      out.push({ y, c, z: zz, ok: verifyT(y, c, zz) });
      if (!verifyT(y, c, zz)) break;
    }
    return out;
  };
  const verifyT = (y: bigint, c: bigint, z: bigint) => md(modPow(b, z, p) * modPow(kinv, c, p), p) === y;
  const trans = useMemo(() => run(makeRng(seed), honest, rounds), [seed, honest, rounds, k, cBits]); // eslint-disable-line react-hooks/exhaustive-deps
  const accepted = trans.length === rounds && trans.every((t) => t.ok);
  const stats = useMemo(() => {
    const rng = makeRng(seed + 999);
    let acc = 0;
    const T = 2000;
    for (let i = 0; i < T; i++) {
      const tr = run(rng, false, rounds);
      if (tr.length === rounds && tr.every((t) => t.ok)) acc++;
    }
    return acc / T;
  }, [seed, rounds, k, cBits]); // eslint-disable-line react-hooks/exhaustive-deps
  // simulator: choose c and z first, then y = b^z κ^(−c)
  const sim = useMemo(() => {
    const rng = makeRng(seed + 17);
    return Array.from({ length: 3 }, () => {
      const c = BigInt(rng.int(0, C - 1));
      const z = BigInt(rng.int(0, 1018));
      const y = md(modPow(b, z, p) * modPow(kinv, c, p), p);
      return { y, c, z, ok: verifyT(y, c, z) };
    });
  }, [seed, C, k]); // eslint-disable-line react-hooks/exhaustive-deps
  // special soundness: same commitment answered for two challenges
  const r0 = 500n;
  const y0 = modPow(b, r0, p);
  const z1 = md(K * 1n + r0, q);
  const z2 = md(K * 0n + r0, q);
  const extracted = md(z1 - z2, q);
  return (
    <VizFrame
      title="Zero-knowledge identification: Schnorr’s protocol"
      caption="Commitment y = b^r, challenge c, response z = k·c + r (mod q); accept iff b^z·κ^(−c) = y. Completeness: an honest prover always passes. Soundness: answering two different challenges for one commitment reveals k, so a prover without k passes a round only by guessing c. Zero knowledge: transcripts can be simulated without k."
    >
      <div className="viz-controls">
        <Slider label="prover’s secret k" value={k} min={1} max={1018} step={1} onChange={setK} />
        <Slider label="challenge bits per round" value={cBits} min={1} max={4} step={1} onChange={setCBits} format={(v) => `${v} (|C| = ${2 ** v})`} />
        <Slider label="rounds t" value={rounds} min={1} max={10} step={1} onChange={setRounds} />
        <Seg value={honest ? 'h' : 'c'} onChange={(v) => setHonest(v === 'h')} options={[{ v: 'h', label: 'honest prover (knows k)' }, { v: 'c', label: 'cheating prover' }]} />
        <div>
          <button className="btn sm" onClick={() => setSeed(seed + 1)}>
            Run again
          </button>
        </div>
      </div>
      <div className="scroll-x">
        <table className="data-table">
          <thead>
            <tr>
              <th>round</th>
              <th className="num">commitment y</th>
              <th className="num">challenge c</th>
              <th className="num">response z</th>
              <th>check</th>
            </tr>
          </thead>
          <tbody>
            {trans.map((t, i) => (
              <tr key={i}>
                <td>{i + 1}</td>
                <td className="num">{String(t.y)}</td>
                <td className="num">{String(t.c)}</td>
                <td className="num">{String(t.z)}</td>
                <td>{t.ok ? '✓' : '✗ reject'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <span className={`verdict ${accepted ? 'good' : 'bad'}`}>{accepted ? 'verifier accepts' : 'verifier rejects'}</span>
      <KV
        items={[
          { k: 'cheater success (2000 runs)', v: stats.toFixed(4) },
          { k: 'theory (1/|C|)^t', v: (1 / C ** rounds).toExponential(2) },
          { k: 'public key κ', v: String(kappa) },
        ]}
      />
      <h4 style={{ margin: '12px 0 4px' }}>Simulator (no secret needed)</h4>
      <p className="small">Pick c and z at random and set y = b^z·κ^(−c). These triples verify and have exactly the distribution of honest transcripts (y uniform in ⟨b⟩, c uniform, z uniform) — so a transcript teaches the verifier nothing it could not produce itself. (With an honest verifier; against a cheating verifier the simulator rewinds when its guess of c is wrong.)</p>
      <div className="small mono">
        {sim.map((s, i) => (
          <div key={i}>
            (y, c, z) = ({String(s.y)}, {String(s.c)}, {String(s.z)}) {s.ok ? '✓' : '✗'}
          </div>
        ))}
      </div>
      <h4 style={{ margin: '12px 0 4px' }}>Special soundness (knowledge extractor)</h4>
      <p className="small">
        Rewind the prover after it committed to y = {String(y0)} and ask two challenges: c = 1 gives z = {String(z1)}, c = 0 gives z = {String(z2)}. Then k = (z₁ − z₂)/(c₁ − c₂) mod q = <b>{String(extracted)}</b>. Anyone who can answer
        two challenges knows k. The Fiat–Shamir trick replaces the verifier’s challenge by c = h(m ‖ y), giving Schnorr signatures.
      </p>
    </VizFrame>
  );
}
